// The design pack's art, inlined as data URIs so the game stays a single file (the LMS sandbox only
// allows `data:` images). The files are generated by scripts/make-design-assets.mjs from design-source/.
import { meta } from "./meta.js";

const raster = import.meta.glob("./img/*.webp", { eager: true, query: "?inline", import: "default" });
const vector = import.meta.glob("./svg/*.svg", { eager: true, query: "?inline", import: "default" });
const find = (table, dir, ext) => (name) => {
  const value = table[`./${dir}/${name}.${ext}`];
  if (!value) throw new Error(`Unknown design asset: ${name}`);
  return value;
};
export const img = find(raster, "img", "webp");
export const svg = find(vector, "svg", "svg");
// Trimmed sprite size in pixels, plus (for the backdrop) its top-row colour.
export const sizeOf = (name) => {
  if (!meta[name]) throw new Error(`Unknown design sprite: ${name}`);
  return meta[name];
};
// The pack's skins as CSS custom properties (`--skin-hud`…), set once on the game's root element.
export const skinVars = () => {
  const names = ["panel-hud", "panel-toolbar", "panel-card", "panel-tip", "pill-dark", "pill-gold", "pill-cyan", "modal-frame",
    "toggle-track", "toggle-thumb", "badge-level", "level-dot-active", "level-dot-idle", "level-dot-complete", "check-badge",
    "icon-tile-blue", "icon-tile-green", "icon-tile-purple", "progress-track", "progress-fill", "speech-bubble",
    ...["primary", "secondary", "violet", "selected", "dark"].flatMap((v) => ["default", "hover", "pressed", "disabled"].map((s) => `button-${v}-${s}`))];
  return Object.fromEntries(names.map((n) => [`--skin-${n}`, `url("${svg(n)}")`]));
};
